	private Boolean processShipment(ShipmentDTO shipmentDto, CS status, String user, String department) {
		Optional<Perso> optionalPerso = persoRepo.findById(shipmentDto.getId());
		if (optionalPerso.isPresent()) {
			Perso p = optionalPerso.get();
			p.setStatus(status.getId());
			p.setOBranch(shipmentDto.getOBranch());
			p.setOPxcode(shipmentDto.getOPxcode());
			p.setUpdatedBy(user);
			p.setUpdatedAt(LocalDateTime.now());
			persoRepo.save(p);
			CardRegistrationHistory ch = createCardHistory(shipmentDto.getId(), status.getId(), status.getText(), user,
					department);
			cardHistoryRepo.save(ch);
			return true;
		} else {
			logger.warn("Perso with ID: {} not found", shipmentDto.getId());
			return false;
		}
	}

	private Boolean processCards(ShipmentDTO shipmentDto, CS status, String user, String department) {

		Optional<Perso> optionalPerso = persoRepo.findById(shipmentDto.getId());
		LocalDateTime currentDateTime = LocalDateTime.now();
		if (optionalPerso.isPresent()) {
			Perso p = optionalPerso.get();
			logger.info("Processing Card: {}", p);
			p.setStatus(status.getId());
			p.setUpdatedAt(currentDateTime);
			p.setUpdatedBy(user);
			p.setUpdatedAt(LocalDateTime.now());
			persoRepo.save(p);
			CardRegistrationHistory ch = createCardHistory(shipmentDto.getId(), status.getId(), status.getText(), user,
					department);
			cardHistoryRepo.save(ch);
			return true;
		} else {
			logger.warn("Perso with ID: {} not found", shipmentDto.getId());
			return false;
		}
	}
	private Boolean processPins(String cardNumber, CS status, String user, String department) {
		logger.info("Radi aktivaciju pina cardNumber {}", cardNumber);
		List<Perso> pinPerso = persoRepo.findByCardNumber(cardNumber);
		LocalDateTime currentDateTime = LocalDateTime.now();

		if (pinPerso.isEmpty()) {
			throw new CardActivationException(400, "Gre­ka: Ne nalazimo karticu: " + cardNumber +
					", pa je nemoguŽØe promeniti status na activated.", "Process error", ACTIVATE_CARD_URL + cardNumber);
		}

		// Filtriramo samo redove gde je type = 'p'
		List<Perso> validPins = pinPerso.stream()
				.filter(perso -> "p".equals(perso.getType()))
				.collect(Collectors.toList());

		if (validPins.isEmpty()) {
			throw new CardActivationException(400, "Gre­ka: Nema validnog PIN-a za karticu: " + cardNumber +
					", pa je nemoguŽØe promeniti status na activated.", "Process error", ACTIVATE_CARD_URL + cardNumber);
		}

		for (Perso p : validPins) {
			logger.info("Processing Card: {}", p);
			p.setStatus(status.getId());
			p.setUpdatedAt(currentDateTime);
			p.setUpdatedBy(user);
			persoRepo.save(p);

			CardRegistrationHistory ch = createCardHistory(p.getId(), status.getId(), status.getText(), user, department);
			cardHistoryRepo.save(ch);
		}

		return true;
	}


	private CardRegistrationHistory createCardHistory(Integer persoId, String statusId, String status, String updatedBy,
			String branch) {
		CardRegistrationHistory ch = new CardRegistrationHistory();
		ch.setPersoId(persoId);
		ch.setUpdatedBy(updatedBy);
		ch.setUpdatedAt(LocalDateTime.now());
		ch.setStatusId(statusId);
		ch.setStatusDescription(status);
		ch.setOpu(branch);
		logger.debug("Created CardRegistrationHistory for Perso ID: {}", persoId);
		return ch;
	}

	@Override
	public List<Perso> getAllCibBySearchForm(PersoSearchForm psf) {
		logger.info("Get search form - getAllCibBySearchForm: {}", psf.toString());
		CriteriaBuilder cb = entityManager.getCriteriaBuilder();
		CriteriaQuery<Perso> cq = cb.createQuery(Perso.class);
		Root<Perso> perso = cq.from(Perso.class);
		List<Predicate> predicates = new ArrayList<>();

		// Odmah dodaje da Delivery methoda na firmu
		predicates.add(cb.equal(perso.get("deliverymethode"), "ex"));
		
		// Odmah dodaje da cibBranch
		predicates.add(cb.equal(perso.get("cibDepartment"), psf.getDepartment()));

		// Filter by cibBatch
		if (psf.getCibBatch() != null && !psf.getCibBatch().isEmpty()) {
			predicates.add(cb.equal(perso.get("cibBatch"), psf.getCibBatch()));
		}
		
		// Filter by type
		if (psf.getType() != null && !psf.getType().isEmpty()) {
			predicates.add(cb.equal(perso.get("type"), psf.getType()));
		}

		// Filter by clientNumber
		if (psf.getClientNumber() != null && !psf.getClientNumber().isEmpty()) {
			predicates.add(cb.like(perso.get("clientNumber"), "%" + psf.getClientNumber() + "%"));
		}

		// Filter by cardNumber
		if (psf.getCardNumber() != null && !psf.getCardNumber().isEmpty()) {
			String cardTrimed = psf.getCardNumber().trim();
			String firstFour = cardTrimed.substring(0, 4);
			int start = cardTrimed.length() - 4;
			String lastFour = cardTrimed.substring(start, cardTrimed.length());
			predicates.add(cb.like(perso.get("cardFirstFour"), "%" + firstFour + "%"));
			predicates.add(cb.like(perso.get("cardLastFour"), "%" + lastFour + "%"));
		}

		// Filter by dateRange
		if (psf.getDateRange() != null && !psf.getDateRange().isEmpty()) {
			if (psf.getDateRange().size() > 0 && psf.getDateRange().get(0) != null) {
				LocalDateTime startDate = psf.getDateRange().get(0).toLocalDate().atStartOfDay();
				predicates.add(cb.greaterThanOrEqualTo(perso.get("fileImportTime"), Timestamp.valueOf(startDate)));
			}
			if (psf.getDateRange().size() > 1 && psf.getDateRange().get(1) != null) {
				LocalDateTime endDate = psf.getDateRange().get(1).toLocalDate().atTime(LocalTime.MAX);
				predicates.add(cb.lessThanOrEqualTo(perso.get("fileImportTime"), Timestamp.valueOf(endDate)));
			}
		}

		// Filter by OPxcode
		if (psf.getPxCode() != null && !psf.getPxCode().isEmpty()) {
			predicates.add(cb.equal(perso.get("OPxcode"), psf.getPxCode()));
		}

		// Filter by inStatus (if list contains statuses)
		if (psf.getInStatus() != null && !psf.getInStatus().isEmpty()) {
			predicates.add(perso.get("status").in(psf.getInStatus()));
		}

		// is Not null px if branch searhc
		//if (psf.isBranchRole()) {
		//	predicates.add(cb.isNotNull(perso.get("OPxcode")));
		//}

		// Apply where conditions
		cq.where(predicates.toArray(new Predicate[0]));

		List<Perso> pins = entityManager.createQuery(cq).getResultList();
		pins.forEach(this::maskedCardNumber); // Mask card number if needed
		return pins;
	}

	public void maskedCardNumber(Perso perso) {
		String cardNumber = perso.getCardNumber().trim();
		if (cardNumber == null || cardNumber.length() != 16) {
			return;
		}
		String first4 = cardNumber.substring(0, 4);
		String last4 = cardNumber.substring(12, 16);
		String maskedNumber = first4 + " **** **** " + last4;
		perso.setCardNumber(maskedNumber);
	}
	public void maskedCardNumberEx(PersoEx perso) {
		if (perso.getCardNumber() == null) {
			return; // Ako je null, izlazi iz metode
		}
		String cardNumber = perso.getCardNumber().trim();

		if (cardNumber.length() != 16) {
			return; // Ako nije taŽ?no 16 cifara, izlazi iz metode
		}
		String first4 = cardNumber.substring(0, 4);
		String last4 = cardNumber.substring(12, 16);
		String maskedNumber = first4 + " **** **** " + last4;
		perso.setCardNumber(maskedNumber);
	}


	@Override
