		if (!PX_PATTERN.matcher(px).matches()) {
			logger.warn("Nevalidan PX kod: {}", px);
			throw new IllegalArgumentException("PX kod mo_e sadr_ati samo velika slova i brojeve, maksimalno 20 karaktera.");
