	@GetMapping("/migrateTempReport")
	public String migrateTempReport() {
		long startTime = System.currentTimeMillis();
		logger.info("*********************** BEGIN migrateTempReport ****************");
		try {
			// Konekcija na AS400 DB2
			DriverManager.registerDriver(new com.ibm.as400.access.AS400JDBCDriver());
			Connection conDb2 = DriverManager.getConnection(url, userName, password);

			// Konekcija na Oracle
			Connection conOracle = DriverManager.getConnection(oracleUrl, oracleUser, oraclePassword);

			// Brisanje podataka iz Oracle tabele pre migracije
			String truncateQuery = "TRUNCATE TABLE TBL_TEMP_REPORT";
			try (Statement truncateStmt = conOracle.createStatement()) {
				truncateStmt.executeUpdate(truncateQuery);
				logger.info("Oracle tabela TBL_TEMP_REPORT je obrisana.");
			}

			conOracle.setAutoCommit(false);

			String selectQuery = """
            SELECT a.trpano, a.trsqno, bmf.b40opu, bmf.b40gir, bmf.B40CLT, bmf.b40acc,
                   bp.b00clt, b0x.b00bcx, bceg.sbhdiv, bRM.sbxceg
            FROM BEZVD02.CCTR00 a
            INNER JOIN (SELECT tr.trpano, MIN(tr.trsqno) AS seq FROM BEZVD02.CCTR00 tr GROUP BY tr.trpano) b
                ON a.trpano = b.trpano AND a.trsqno = b.seq
            INNER JOIN BEDAY03.bmf40p bmf ON a.tracno = bmf.b40acc AND bmf.b40sts <> 'C'
            INNER JOIN BEDAY03.bmf00p bp ON bmf.b40clt = bp.b00clt
            INNER JOIN BEDAY03.bmf00xud b0x ON b0x.b00clt = bp.b00clt
            LEFT JOIN BEDAY03.sdfbxp bRM ON bRM.sbxcex = b0x.b00bcx
            LEFT JOIN BEDAY03.sdfbhp bceg ON bRM.sbxceg = bceg.sbhceg
        """;
			PreparedStatement stmt = conDb2.prepareStatement(selectQuery);
			ResultSet rs = stmt.executeQuery();

			// Priprema batch insert-a
			String insertQuery = """
            INSERT INTO TBL_TEMP_REPORT (TRPANO, TRSQNO, B40OPU, B40GIR, B40CLT, B40ACC, B00CLT, B00BCX, SBHDIV, SBXCEG)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """;
			PreparedStatement oracleStmt = conOracle.prepareStatement(insertQuery);

			int batchSize = 1000;
			int count = 0;

			while (rs.next()) {
				oracleStmt.setLong(1, rs.getLong("TRPANO"));
				oracleStmt.setInt(2, rs.getInt("TRSQNO"));
				oracleStmt.setString(3, rs.getString("B40OPU"));
				oracleStmt.setString(4, rs.getString("B40GIR"));
				oracleStmt.setString(5, rs.getString("B40CLT"));
				oracleStmt.setString(6, rs.getString("B40ACC"));
				oracleStmt.setString(7, rs.getString("B00CLT"));
				oracleStmt.setString(8, rs.getString("B00BCX"));
				oracleStmt.setString(9, rs.getString("SBHDIV"));
				oracleStmt.setString(10, rs.getString("SBXCEG"));

				oracleStmt.addBatch();
				count++;

				if (count % batchSize == 0) {
					oracleStmt.executeBatch();
					logger.info("Migrirano {} slogova...", count);
				}
			}

			// Izvr­i preostale podatke
			oracleStmt.executeBatch();
			conOracle.commit();

			// Brojanje slogova u AS400
			String countAS400Query = "SELECT COUNT(*) FROM (" + selectQuery + ")";
			PreparedStatement stmtAS400 = conDb2.prepareStatement(countAS400Query);
			ResultSet rsAS400 = stmtAS400.executeQuery();
			rsAS400.next();
			int totalAS400 = rsAS400.getInt(1);

			// Brojanje slogova u Oracle
			String countOracleQuery = "SELECT COUNT(*) FROM TBL_TEMP_REPORT";
			PreparedStatement stmtOracle = conOracle.prepareStatement(countOracleQuery);
			ResultSet rsOracle = stmtOracle.executeQuery();
			rsOracle.next();
			int totalOracle = rsOracle.getInt(1);

			// Zatvaranje konekcija
			rs.close();
			stmt.close();
			conDb2.close();
			oracleStmt.close();
			conOracle.close();
			rsAS400.close();
			stmtAS400.close();
			rsOracle.close();
			stmtOracle.close();

			long endTime = System.currentTimeMillis(); // Kraj tajminga
			logger.info("*********************** END migrateTempReport ****************");
			logger.info("AS400 COUNT: {}, Oracle COUNT: {}", totalAS400, totalOracle);
			logger.info("Ukupno trajanje: {} sekundi", (endTime - startTime) / 1000);

			if (totalAS400 == totalOracle) {
				logger.info("Migracija uspe­na! Broj slogova se poklapa.");
			//	return "Podaci uspe­no migrirani iz AS400 u Oracle!";
			} else {
				logger.warn("Razlika u broju slogova! AS400: {}, Oracle: {}", totalAS400, totalOracle);
			//	return "ERROR";
			}
				return "SUCESS";

		} catch (Exception e) {
			logger.error("Gre­ka prilikom migracije", e);
			return "ERROR";
		}
	}


