	@Override
//	@Scheduled(cron = "0 0 9 * * *") // Azuriranje tbl_nexi_code_core a zatim BRANCH-ova na svakih 7 dana jer nema potrebe svaki dan.... razmilsiti
	@Scheduled(cron = "0 0 9 */7 * *") // Azuriranje tbl_nexi_code_core a zatim BRANCH-ova na svakih 7 dana jer nema potrebe svaki dan.... razmilsiti
	public void syncBranch() throws SQLException {
		logger.info("***********************BEGIN syncBranch****************");
		DriverManager.registerDriver(new com.ibm.as400.access.AS400JDBCDriver());
		Connection con_db2 = DriverManager.getConnection(url, userName, password);
		String SQL_QUERY = " SELECT TRIM(REPLACE(REPLACE(SUBSTRING(VDVDTA, INSTR(VDVDTA, 'BRFDSC') + 7), ',', ''), ')', '')) AS nexicode, \n"
				+ "   trim(VDVKEY) branch,\n"
				+ "   TRIM(SUBSTR(SUBSTR(VDVDTA, INSTR(VDVDTA, 'BRZIPC') + 7), 1, 5)) AS zip, \n"
				+ "   TRIM(SUBSTR(VDVDTA, INSTR(VDVDTA, 'BRCITY') + 7, \n"
				+ "       INSTR(SUBSTR(VDVDTA, INSTR(VDVDTA, 'BRCITY') + 7), ')') - 1)) AS city, \n"
				+ "       TRIM(SUBSTR(VDVDTA, INSTR(VDVDTA, 'BRSTR') + 8, \n"
				+ "       INSTR(SUBSTR(VDVDTA, INSTR(VDVDTA, 'BRSTR') + 8), '''') - 1)) AS address, \n"
				+ "CONCAT(CONCAT(REPLACE(SUBSTRING(VDVDTA,instr(VDVDTA,'BRNAME')+7,instr(VDVDTA,')',instr(VDVDTA,'BRNAME')+1)-instr(VDVDTA,'BRNAME')-7),'''',''),' - '),      \n"
				+ "REPLACE(SUBSTRING(VDVDTA,instr(VDVDTA,'BRSTRT')+7,instr(VDVDTA,')',instr(VDVDTA,'BRSTRT')+1)-instr(VDVDTA,'BRSTRT')-7),'''','')) description\n"
				+ "FROM bezvd02.CC##VD00  WHERE vdapva ='BRCH' AND instr(VDVDTA,'BRSTRT')<>0\n" + "ORDER BY 1,2 ";

		try (PreparedStatement preparedStatement = con_db2.prepareStatement(SQL_QUERY)) {
			ResultSet rs = preparedStatement.executeQuery();

			List<NexiCore> newListForSave = new ArrayList<>();
			while (rs.next()) {
				String nexiCode = rs.getString("nexicode");
				String branch = rs.getString("branch");
				String zip = rs.getString("zip");
				String city = rs.getString("city");
				String address = rs.getString("address");
				String description = rs.getString("description");

				NexiCore newNexiCore = new NexiCore();
				newNexiCore.setNexiCode(nexiCode);
				newNexiCore.setBranch(branch);
				newNexiCore.setZip(zip);
				newNexiCore.setCity(city);
				newNexiCore.setAddress(address);
				newNexiCore.setDescription(description);
				newNexiCore.setUpdatedBy("system");
				newNexiCore.setUpdatedAt(LocalDateTime.now());
				newListForSave.add(newNexiCore);
			}
			con_db2.close();
			logger.info("newListForSave: {}", newListForSave.size());
			if (newListForSave != null && newListForSave.size() > 0) {
				nexiCoreRepository.deleteAll();
				for (NexiCore nexiCoreForSave : newListForSave) {
					logger.info("nexiCoreForSave: {}", nexiCoreForSave.getNexiCode());
					nexiCoreRepository.save(nexiCoreForSave);
				}
				updateBranchContact();
			} else {
				logger.error("Nemamo podatka za NEXICODE sa core-a!!!");
			}
		} catch (Exception e) {
			logger.error("Greska u SyncBranch", e);
		}
	}

